// Lit le mail envoyé par le formulaire du site et en tire les coordonnées du prospect.
// Le mail vient soit du déclencheur (nouvelle demande), soit de « Retrouver la demande »
// (le prospect a cliqué sur un créneau : on relit sa demande dans Gmail).
// On cherche d'abord les lignes « Nom : … », « Téléphone : … », « Email : … » puis, à défaut,
// le premier numéro et la première adresse trouvés dans le texte.

const reglages = $('Réglages').first().json;

const chiffres = (v) => String(v ?? '').replace(/\D/g, '');
const propre = (v, max = 80) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const liste = (v) => String(v ?? '').toLowerCase().split(/[\s,;]+/).filter(Boolean);

// Adresses qui ne sont jamais celles du prospect (la boîte de l'entreprise).
const internes = liste(reglages.adresses_internes);
// Numéro de l'entreprise, écrit 0XXXXXXXXX, pour ne pas le prendre pour celui du prospect.
const national = (v) => chiffres(v).replace(/^(?:0033|33)(?=\d{9}$)/, '0');
const telephoneEntreprise = national(reglages.telephone_entreprise);

const ADRESSE = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi;
const ADRESSE_SEULE = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i;
const TELEPHONE_FR = /(?:(?:\+|00)33[\s.-]?(?:\(0\)[\s.-]?)?|0)[1-9](?:[\s.-]?\d{2}){4}/g;

const ENTITES = {
  nbsp: ' ', amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", rsquo: '’', lsquo: '‘', laquo: '«', raquo: '»',
  euro: '€', deg: '°', eacute: 'é', egrave: 'è', ecirc: 'ê', euml: 'ë', agrave: 'à', acirc: 'â', ccedil: 'ç',
  ugrave: 'ù', ucirc: 'û', ocirc: 'ô', icirc: 'î', iuml: 'ï', oelig: 'œ',
};
const MAJUSCULES = { Eacute: 'É', Egrave: 'È', Ecirc: 'Ê', Agrave: 'À', Ccedil: 'Ç' };

function decoder(texte) {
  const caractere = (n) => (n > 0 && n <= 0x10ffff ? String.fromCodePoint(n) : '');
  return texte
    .replace(/&#(\d{1,7});/g, (_, n) => caractere(Number(n)))
    .replace(/&#x([0-9a-f]{1,6});/gi, (_, n) => caractere(parseInt(n, 16)))
    .replace(/&([a-z]+);/gi, (tout, nom) => MAJUSCULES[nom] ?? ENTITES[nom.toLowerCase()] ?? tout);
}

/** Texte du mail : la version texte si elle existe, sinon la version HTML débarrassée de ses balises. */
function texteDe(mail) {
  let texte = typeof mail.text === 'string' ? mail.text : '';
  if (!texte.trim()) {
    const html = [mail.html, mail.textAsHtml].find((v) => typeof v === 'string' && v.trim()) ?? '';
    texte = html
      .replace(/<(style|script|head)\b[\s\S]*?<\/\1>/gi, ' ')
      .replace(/<br\s*\/?>|<\/(?:p|div|tr|li|h[1-6]|table)>/gi, '\n')
      .replace(/<\/t[dh]>/gi, '\t')
      .replace(/<[^>]+>/g, ' ');
  }
  if (!texte.trim() && typeof mail.snippet === 'string') texte = mail.snippet;
  return decoder(texte)
    .replace(/\r\n?/g, '\n')
    .replace(/ /g, ' ')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/** Adresses d'un champ d'en-tête, quelle que soit sa forme (objet { value: [...] } ou texte). */
function adressesDe(champ) {
  if (!champ) return [];
  if (typeof champ === 'string') return (champ.match(ADRESSE) ?? []).map((a) => a.toLowerCase());
  if (Array.isArray(champ)) return champ.flatMap(adressesDe);
  if (Array.isArray(champ.value)) return champ.value.map((v) => String(v.address ?? '').toLowerCase()).filter(Boolean);
  if (typeof champ.address === 'string') return [champ.address.toLowerCase()];
  if (typeof champ.text === 'string') return adressesDe(champ.text);
  return [];
}

/** Valeur d'une ligne « Étiquette : valeur » (ou étiquette suivie d'une tabulation / d'un retour à la ligne). */
function champ(texte, etiquettes) {
  for (const etiquette of etiquettes) {
    const motif = new RegExp(
      `(?:^|\\n)[ \\t>*•·-]*(?:${etiquette})[ \\t]*(?:[:=][ \\t]*|\\t+[ \\t]*|[ ]{2,}|\\n)([^\\n]+)`,
      'iu',
    );
    const valeur = motif.exec(texte)?.[1]?.trim() ?? '';
    // Une valeur qui ressemble elle-même à « Étiquette : » veut dire que le champ était vide.
    if (valeur && !/^[\p{L} '’-]{2,25}[ \t]*[:=]/u.test(valeur)) return valeur;
  }
  return '';
}

function lire(mail) {
  const texte = texteDe(mail);
  const entetes = mail.headers ?? {};

  // --- Adresse e-mail du prospect : « Répondre à », puis ligne « Email : … », puis première adresse du texte.
  const exclues = new Set([...internes, ...adressesDe(mail.from ?? mail.From), ...adressesDe(mail.to ?? mail.To)]);
  const candidates = [
    ...adressesDe(mail.replyTo ?? entetes['reply-to']),
    ...adressesDe(champ(texte, ['Adresse e-?mail', 'E-?mail', 'Courriel', 'Mail'])),
    ...adressesDe(texte),
  ];
  const email = candidates.find((a) => ADRESSE_SEULE.test(a) && !exclues.has(a)) ?? '';

  // --- Téléphone : ligne « Téléphone : … », puis premier numéro français du texte (hors numéro de l'entreprise).
  const numeros = [
    champ(texte, ['T[ée]l[ée]phone(?: portable| mobile)?', 'T[ée]l\\.?', 'Portable', 'Mobile', 'Phone']),
    ...(texte.match(TELEPHONE_FR) ?? []),
  ]
    .map((n) => propre(String(n).match(/[+\d][\d\s.()-]{6,22}\d/)?.[0] ?? '', 25))
    .filter((n) => chiffres(n).length >= 8 && national(n) !== telephoneEntreprise);
  const telephone = numeros[0] ?? '';

  // --- Nom : « Prénom » + « Nom », à défaut le nom affiché dans « Répondre à ».
  const sansSymbole = (v) => (/[@\d]/.test(v) ? '' : propre(v, 60));
  const prenom = sansSymbole(champ(texte, ['Pr[ée]nom']));
  const nomSeul = sansSymbole(champ(texte, ['Nom et pr[ée]nom', 'Nom', 'Name']));
  const nomReponse = sansSymbole(mail.replyTo?.value?.[0]?.name ?? '');
  const nom = [prenom, nomSeul].filter(Boolean).join(' ') || nomReponse;

  // --- Date de réception.
  const date = [mail.date, Number(mail.internalDate)].map((v) => new Date(v)).find((d) => v_valide(d));

  return {
    ref: String(mail.id ?? ''),
    sujet: propre(mail.subject ?? mail.Subject, 150),
    recu_le: date ? date.toISOString() : null,
    nom,
    telephone,
    email,
    texte: texte.slice(0, 3000),
  };
}

function v_valide(date) {
  return date instanceof Date && !Number.isNaN(date.getTime()) && date.getTime() > 0;
}

return $input.all().map((item, index) => ({ json: lire(item.json ?? {}), pairedItem: { item: index } }));

// Calcule les créneaux de rappel proposables (réglages + agenda) et décide de la suite :
//  - une demande arrive par mail        → e-mail avec les boutons de créneaux ;
//  - le prospect clique sur un créneau  → page (questions, autres créneaux ou message) ;
//  - le prospect valide la page         → rappel à ajouter dans l'agenda.
// Les horaires, jours et questions se modifient dans le node « Réglages », pas ici.

const R = $('Réglages').first().json;
const ZONE = 'Europe/Paris';
const maintenant = DateTime.now().setZone(ZONE);

const JOURS = ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche'];
const MOIS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'];

const deux = (n) => String(n).padStart(2, '0');
const sansAccent = (v) => String(v ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const chiffres = (v) => String(v ?? '').replace(/\D/g, '');
const vide = (v) => v === undefined || v === null || String(v).trim() === '';
const nombre = (v, defaut) => (!vide(v) && Number.isFinite(Number(v)) ? Number(v) : defaut);
const vrai = (v, defaut) => (vide(v) ? defaut : !(v === false || /^(false|faux|non|0)$/i.test(String(v).trim())));
const un = (v) => (Array.isArray(v) ? v[0] : v);
const echapper = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const heure = (d) => `${d.hour}h${deux(d.minute)}`;
const libelleJour = (d) => `${JOURS[d.weekday - 1]} ${d.day === 1 ? '1er' : d.day} ${MOIS[d.month - 1]}`;

// ---------------------------------------------------------------- Lecture des réglages

/** « 11:30-11:45, 17:30-18:00 » (ou 11h30-11h45) → horaires de la journée, dans l'ordre. */
function lireCreneaux(texte) {
  const horaires = new Map();
  const motif = /(\d{1,2})\s*[h:]\s*(\d{2})?\s*(?:-|–|—|à|a|>)\s*(\d{1,2})\s*[h:]\s*(\d{2})?/gi;
  for (const r of String(texte ?? '').matchAll(motif)) {
    const [h1, m1, h2, m2] = [r[1], r[2] ?? 0, r[3], r[4] ?? 0].map(Number);
    if (h1 < 24 && h2 < 24 && m1 < 60 && m2 < 60 && h2 * 60 + m2 > h1 * 60 + m1) {
      const code = `${deux(h1)}${deux(m1)}-${deux(h2)}${deux(m2)}`;
      horaires.set(code, { h1, m1, h2, m2, code });
    }
  }
  return [...horaires.values()].sort((a, b) => a.h1 * 60 + a.m1 - (b.h1 * 60 + b.m1));
}

/** « lundi, mardi » ou « lundi au vendredi » → numéros de jours (1 = lundi … 7 = dimanche). */
function lireJours(texte) {
  const mots = sansAccent(texte).replace(/([a-z])\s*[-–—]\s*([a-z])/g, '$1 au $2').split(/[^a-z]+/).filter(Boolean);
  const rang = (mot) => (mot && mot.length >= 3 ? JOURS.findIndex((j) => j.startsWith(mot.slice(0, 3))) : -1);
  const trouves = new Set();
  for (let i = 0; i < mots.length; i++) {
    const debut = rang(mots[i]);
    if (debut < 0) continue;
    const fin = ['au', 'a'].includes(mots[i + 1]) ? rang(mots[i + 2]) : -1;
    if (fin < 0) {
      trouves.add(debut + 1);
      continue;
    }
    for (let k = debut; ; k = (k + 1) % 7) {
      trouves.add(k + 1);
      if (k === fin) break;
    }
    i += 2;
  }
  return trouves.size ? [...trouves].sort() : [1, 2, 3, 4, 5];
}

/** « 24/12/2026, 31/12/2026 » ou une période « 24/12/2026 au 02/01/2027 » → dates fermées (AAAA-MM-JJ). */
function lireDates(texte) {
  const source = String(texte ?? '');
  const dates = [];
  for (const r of source.matchAll(/(\d{1,2})\/(\d{1,2})\/(\d{4}|\d{2})|(\d{4})-(\d{2})-(\d{2})/g)) {
    const date = r[4]
      ? DateTime.fromObject({ year: +r[4], month: +r[5], day: +r[6] }, { zone: ZONE })
      : DateTime.fromObject({ year: r[3].length === 2 ? 2000 + +r[3] : +r[3], month: +r[2], day: +r[1] }, { zone: ZONE });
    if (date.isValid) dates.push({ date, debut: r.index, fin: r.index + r[0].length });
  }
  const fermees = new Set();
  for (let i = 0; i < dates.length; i++) {
    const { date, fin } = dates[i];
    const suivante = dates[i + 1];
    const entre = suivante ? sansAccent(source.slice(fin, suivante.debut)).trim() : '';
    const periode = suivante && /^(-|–|—|>|au|a)$/.test(entre) && suivante.date >= date && suivante.date.diff(date, 'days').days <= 366;
    if (!periode) {
      fermees.add(date.toISODate());
      continue;
    }
    for (let jour = date; jour <= suivante.date; jour = jour.plus({ days: 1 })) fermees.add(jour.toISODate());
    i++;
  }
  return fermees;
}

/** Jours fériés français d'une année (dates fixes + lundi de Pâques, Ascension, lundi de Pentecôte). */
function joursFeries(annee) {
  const a = annee % 19;
  const b = Math.floor(annee / 100);
  const c = annee % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const paques = DateTime.fromObject(
    { year: annee, month: Math.floor((h + l - 7 * m + 114) / 31), day: ((h + l - 7 * m + 114) % 31) + 1 },
    { zone: ZONE },
  );
  const fixes = ['01-01', '05-01', '05-08', '07-14', '08-15', '11-01', '11-11', '12-25'].map((jour) => `${annee}-${jour}`);
  return new Set([...fixes, ...[1, 39, 50].map((n) => paques.plus({ days: n }).toISODate())]);
}

const horairesDuJour = lireCreneaux(R.creneaux);
if (!horairesDuJour.length) {
  throw new Error('Réglages : aucun horaire lisible dans « creneaux » (exemple : 11:30-11:45, 17:30-17:45).');
}
const joursOuverts = lireJours(R.jours);
const joursFermes = lireDates(R.jours_fermes);
const feriesFermes = vrai(R.jours_feries_fermes, true);
const heuresProposees = Math.max(1, nombre(R.heures_proposees, 48));
const delaiMinimum = Math.max(0, nombre(R.delai_minimum_minutes, 60));
const questionsObligatoires = vrai(R.questions_obligatoires, true);

// Questions de la page : question_1 / reponses_1, question_2 / reponses_2… (réponses séparées par « ; »).
const questions = [];
for (let n = 1; n <= 9; n++) {
  const titre = String(R[`question_${n}`] ?? '').trim();
  const reponses = String(R[`reponses_${n}`] ?? '').split(';').map((r) => r.trim()).filter(Boolean);
  if (titre && reponses.length >= 2) questions.push({ id: `q${n}`, titre, reponses });
}

// ---------------------------------------------------------------- Créneaux proposables

const feries = new Map();
function estOuvert(jour) {
  if (!joursOuverts.includes(jour.weekday) || joursFermes.has(jour.toISODate())) return false;
  if (!feriesFermes) return true;
  if (!feries.has(jour.year)) feries.set(jour.year, joursFeries(jour.year));
  return !feries.get(jour.year).has(jour.toISODate());
}

function creneau(debut, fin) {
  return {
    code: `${debut.toFormat('yyyyLLdd')}-${debut.toFormat('HHmm')}-${fin.toFormat('HHmm')}`,
    debut: debut.toISO(),
    fin: fin.toISO(),
    jour: libelleJour(debut),
    de: heure(debut),
    a: heure(fin),
  };
}

/** Créneaux des prochaines heures ouvrées : les jours fermés ne comptent pas dans le délai. */
function creneauxProposes(heures) {
  const auPlusTot = maintenant.plus({ minutes: delaiMinimum });
  let limite = maintenant.plus({ hours: heures });
  const liste = [];
  let jour = maintenant.startOf('day');
  // 31 jours au plus : c'est aussi la période d'agenda lue par « Agenda : créneaux occupés ».
  for (let n = 0; n < 31 && jour <= limite; n++) {
    const lendemain = jour.plus({ days: 1 });
    if (!estOuvert(jour)) {
      limite = limite.plus(lendemain.diff(jour < maintenant ? maintenant : jour));
    } else {
      for (const h of horairesDuJour) {
        const debut = jour.set({ hour: h.h1, minute: h.m1 });
        if (debut >= auPlusTot && debut <= limite) liste.push(creneau(debut, jour.set({ hour: h.h2, minute: h.m2 })));
      }
    }
    jour = lendemain;
  }
  return liste;
}

// ---------------------------------------------------------------- Agenda : ce qui est déjà pris

const refDe = (evenement) => /Réf\. demande : ([0-9a-f]{10,32})/i.exec(String(evenement.description ?? ''))?.[1] ?? '';

/** Période occupée par un événement de l'agenda ; rien si l'événement ne bloque pas (annulé, « disponible », refusé). */
function periode(evenement) {
  if (evenement.status === 'cancelled' || evenement.transparency === 'transparent') return null;
  if (Array.isArray(evenement.attendees) && evenement.attendees.some((p) => p.self && p.responseStatus === 'declined')) return null;
  const instant = (borne) => {
    if (borne?.dateTime) return DateTime.fromISO(borne.dateTime, { setZone: true });
    if (borne?.date) return DateTime.fromISO(borne.date, { zone: ZONE });
    return null;
  };
  const debut = instant(evenement.start);
  const fin = instant(evenement.end);
  if (!debut?.isValid || !fin?.isValid) return null;
  return { debut, fin, ref: refDe(evenement) };
}

const evenements = $input.all().map((item) => item.json ?? {});
const erreurAgenda = evenements.find((e) => e.error !== undefined && e.id === undefined)?.error;
const dejaVus = new Set();
const periodes = [];
for (const evenement of evenements) {
  if (!evenement.id || dejaVus.has(evenement.id)) continue;
  dejaVus.add(evenement.id);
  const occupee = periode(evenement);
  if (occupee) periodes.push(occupee);
}

const estPris = (c) => periodes.some((p) => p.debut < DateTime.fromISO(c.fin) && p.fin > DateTime.fromISO(c.debut));

// Si tout est pris sur la période prévue, on regarde un jour plus loin, jusqu'à trouver un créneau libre.
let proposes = [];
let libres = [];
for (let heures = heuresProposees; !libres.length && heures <= heuresProposees + 24 * 21; heures += 24) {
  proposes = creneauxProposes(heures);
  libres = proposes.filter((c) => !estPris(c));
}

/** Créneaux regroupés par jour, avec le lien à cliquer. */
function parJour(creneaux, ref) {
  const jours = [];
  for (const c of creneaux) {
    if (jours.at(-1)?.titre !== c.jour) jours.push({ titre: c.jour, creneaux: [] });
    jours.at(-1).creneaux.push({ ...c, lien: lienVers(ref, c.code) });
  }
  return jours;
}

const lienVers = (ref, code) => `${String(R.lien_rappel ?? '').trim()}?ref=${encodeURIComponent(ref)}${code ? `&c=${code}` : ''}`;

// ---------------------------------------------------------------- Cas 1 : demande arrivée par mail

const demandes = $('Lire la demande').all().map((item) => item.json);

if ($('Nouveau mail du site').isExecuted) {
  if (erreurAgenda) {
    throw new Error(`Agenda Google inaccessible : ${erreurAgenda}. Vérifier la connexion du compte dans les nodes « Agenda ».`);
  }
  return demandes.map((demande) =>
    demande.email
      ? { json: { action: 'envoyer', demande, jours: parJour(libres, demande.ref), lien_creneaux: lienVers(demande.ref) } }
      : { json: { action: 'sans_email', demande } },
  );
}

// ---------------------------------------------------------------- Cas 2 et 3 : clic sur un créneau, validation de la page

const validation = $('Validation du rappel').isExecuted;
const parametres = (validation ? R.body : R.query) ?? {};
const demande = demandes[0] ?? {};
const prospect = { ref: demande.ref, nom: demande.nom, telephone: demande.telephone, email: demande.email };
const page = (ecran, contenu = {}) => [{ json: { action: 'page', ecran, demande: prospect, ...contenu } }];

if (!demande.ref) return page('message', { code: 'lien_invalide' });
// Agenda illisible : le prospect voit une page d'excuse et l'exécution est signalée en erreur.
if (erreurAgenda) return [{ json: { action: 'erreur', detail: String(erreurAgenda), demande: prospect } }];

// Un seul rappel par demande : si le prospect en a déjà un à venir, on le lui rappelle.
const mien = periodes.find((p) => p.ref === demande.ref && p.fin > maintenant);
if (mien) {
  const debut = mien.debut.setZone(ZONE);
  const fin = mien.fin.setZone(ZONE);
  return page('message', { code: 'deja_reserve', rappel: { jour: libelleJour(debut), de: heure(debut), a: heure(fin) } });
}

const code = String(un(parametres.c) ?? '').trim();
const autres = { jours: parJour(libres, demande.ref) };
if (!code) return page('creneaux', autres);

const choisi = proposes.find((c) => c.code === code);
if (!choisi) return page('creneaux', { avis: 'indisponible', ...autres });
if (estPris(choisi)) return page('creneaux', { avis: 'pris', ...autres });

// Saisie de la page : numéro à rappeler et réponses (numéro de la réponse choisie, ou null).
const telephone = validation
  ? String(un(parametres.tel) ?? '').replace(/[^\d+ ().-]/g, '').replace(/\s+/g, ' ').trim().slice(0, 30)
  : String(demande.telephone ?? '');
const reponses = questions.map((q) => {
  const choix = String(un(parametres[q.id]) ?? '').trim();
  return /^\d$/.test(choix) && Number(choix) < q.reponses.length ? Number(choix) : null;
});
const formulaire = {
  creneau: choisi,
  questions,
  obligatoires: questionsObligatoires,
  saisie: { telephone, reponses },
  lien_formulaire: String(R.lien_rappel ?? '').trim(),
  lien_creneaux: lienVers(demande.ref),
};

if (!validation) return page('questions', formulaire);

const erreurs = [];
if (chiffres(telephone).length < 8) erreurs.push('telephone');
if (questionsObligatoires && reponses.includes(null)) erreurs.push('questions');
if (erreurs.length) return page('questions', { ...formulaire, erreurs });

// Tout est bon : contenu de l'événement à créer dans l'agenda.
const recu = demande.recu_le ? DateTime.fromISO(demande.recu_le).setZone(ZONE) : null;
const description = [
  'Rappel demandé depuis le site internet.',
  '',
  `Téléphone : ${echapper(telephone)}`,
  demande.nom ? `Nom : ${echapper(demande.nom)}` : null,
  demande.email ? `E-mail : ${echapper(demande.email)}` : null,
  '',
  ...questions.map((q, i) => `${echapper(q.titre)} → ${reponses[i] === null ? '(sans réponse)' : echapper(q.reponses[reponses[i]])}`),
  questions.length ? '' : null,
  `Demande reçue${recu?.isValid ? ` le ${recu.toFormat('dd/LL/yyyy')} à ${heure(recu)}` : ''} :`,
  echapper(demande.texte) || '(texte de la demande introuvable)',
  '',
  `Réf. demande : ${demande.ref}`,
]
  .filter((ligne) => ligne !== null)
  .join('\n');

return [
  {
    json: {
      action: 'reserver',
      debut: choisi.debut,
      fin: choisi.fin,
      titre: `📞 Rappeler ${demande.nom || demande.email || 'un prospect du site'} – ${telephone}`,
      description,
      rappel: { jour: choisi.jour, de: choisi.de, a: choisi.a },
      telephone,
      demande: prospect,
    },
  },
];

// Met en forme ce que « Créneaux et décision » a décidé : l'e-mail avec les boutons de créneaux,
// ou la page affichée au prospect (questions, autres créneaux, confirmation, message).
// Les textes de l'e-mail et le nom de l'entreprise viennent du node « Réglages ».

const R = $('Réglages').first().json;

const e = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
const majuscule = (texte) => texte.charAt(0).toUpperCase() + texte.slice(1);
const paragraphes = (texte) => e(String(texte ?? '').trim()).replace(/\n/g, '<br>');

const COULEUR = /^#[0-9a-f]{6}$/i.test(String(R.couleur ?? '').trim()) ? String(R.couleur).trim() : '#c53535';
const ENTREPRISE = e(R.entreprise || 'Notre entreprise');
const TELEPHONE = e(R.telephone_entreprise);
const APPEL = `tel:${String(R.telephone_entreprise ?? '').replace(/[^\d+]/g, '')}`;
const appelezNous = TELEPHONE ? `appelez-nous au <a href="${APPEL}">${TELEPHONE}</a>` : 'contactez-nous';

// ---------------------------------------------------------------- E-mail envoyé au prospect

// Dans l'e-mail, les styles sont écrits sur chaque balise (les messageries ignorent les feuilles de style).
const appelEmail = TELEPHONE
  ? `appelez-nous au <a href="${APPEL}" style="color:${COULEUR};white-space:nowrap;">${TELEPHONE}</a>`
  : 'contactez-nous';

function boutonEmail(c) {
  return (
    '<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0"><tr>' +
    `<td align="center" bgcolor="${COULEUR}" style="background:${COULEUR};border-radius:6px;mso-padding-alt:12px 6px;">` +
    `<a href="${e(c.lien)}" style="display:block;padding:12px 6px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:20px;font-weight:bold;color:#ffffff;text-decoration:none;white-space:nowrap;border-radius:6px;">${e(c.de)} – ${e(c.a)}</a>` +
    '</td></tr></table>'
  );
}

/** Boutons d'une journée : deux colonnes de même largeur (lisible sur téléphone comme dans Outlook). */
function grilleEmail(creneaux) {
  const lignes = [];
  for (let i = 0; i < creneaux.length; i += 2) {
    const droite = creneaux[i + 1] ? boutonEmail(creneaux[i + 1]) : '&nbsp;';
    lignes.push(
      `<tr><td width="50%" style="padding:0 5px 10px 0;">${boutonEmail(creneaux[i])}</td><td width="50%" style="padding:0 0 10px 5px;">${droite}</td></tr>`,
    );
  }
  return `<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="max-width:340px;">${lignes.join('')}</table>`;
}

function email(d) {
  const texte = 'margin:0 0 16px;';
  const jours = d.jours
    .map((jour) => `<p style="margin:22px 0 10px;font-size:17px;font-weight:bold;">${e(majuscule(jour.titre))}</p>${grilleEmail(jour.creneaux)}`)
    .join('');
  const choix = d.jours.length
    ? `<p style="${texte}">${paragraphes(R.email_intro)}</p>${jours}
       <p style="margin:18px 0 0;">Aucun de ces créneaux ne vous convient ? <a href="${e(d.lien_creneaux)}" style="color:${COULEUR};">Voir les créneaux suivants</a>, répondez à cet e-mail ou ${appelEmail}.</p>`
    : `<p style="${texte}">Nous avons bien reçu votre demande et nous vous en remercions.</p>
       <p style="${texte}">Tous nos créneaux de rappel des prochains jours sont déjà pris : nous vous rappelons dès que possible. Vous pouvez aussi répondre à cet e-mail ou ${appelEmail.replace('appelez-nous', 'nous appeler')}.</p>`;
  const signature = [ENTREPRISE, e(R.adresse_entreprise), TELEPHONE].filter(Boolean).join('<br>');

  return `<!doctype html>
<html lang="fr">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${e(R.email_objet)}</title></head>
<body style="margin:0;padding:0;background:#f5f5f4;">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#f5f5f4" style="background:#f5f5f4;">
<tr><td align="center" style="padding:24px 12px;">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="max-width:560px;background:#ffffff;border-radius:10px;">
<tr><td style="padding:28px 24px;font-family:Arial,Helvetica,sans-serif;font-size:16px;line-height:24px;color:#1c1917;text-align:left;">
<p style="${texte}">Bonjour,</p>
${choix}
<p style="margin:28px 0 0;padding-top:16px;border-top:1px solid #e7e5e4;font-size:14px;line-height:21px;color:#57534e;">${signature}</p>
</td></tr>
</table>
</td></tr>
</table>
</body>
</html>`;
}

// ---------------------------------------------------------------- Pages affichées au prospect

const STYLE = `
*{box-sizing:border-box}
body{margin:0;background:#f5f5f4;color:#1c1917;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;font-size:17px;line-height:1.5;-webkit-text-size-adjust:100%}
main{max-width:30rem;margin:0 auto;padding:1.25rem 1rem 3rem}
.marque{margin:0 0 1rem;font-size:1.125rem;font-weight:800;letter-spacing:.02em;color:${COULEUR}}
.carte{background:#fff;border-radius:14px;padding:1.5rem 1.25rem;box-shadow:0 1px 2px rgba(28,25,23,.06),0 12px 28px -16px rgba(28,25,23,.3)}
h1{margin:0 0 .75rem;font-size:1.5rem;line-height:1.2}
h2{margin:1.5rem 0 .6rem;font-size:1.0625rem}
p{margin:0 0 1rem}
a{color:${COULEUR}}
a[href^="tel:"]{white-space:nowrap}
.resume{margin:0 0 .35rem;padding:.85rem 1rem;border-radius:10px;background:#f5f5f4}
.resume strong{display:block;font-size:1.125rem}
.autre{margin:0 0 1.5rem;font-size:.9375rem}
.alerte{margin:0 0 1.25rem;padding:.75rem 1rem;border-left:4px solid ${COULEUR};border-radius:6px;background:#fdf3f2;font-weight:600}
label.champ,legend{display:block;margin:0 0 .5rem;padding:0;font-weight:700}
fieldset{margin:1.5rem 0 0;padding:0;border:0;min-width:0}
input[type=tel]{width:100%;min-height:3rem;padding:.6rem .8rem;border:2px solid #d6d3d1;border-radius:10px;font:inherit;color:inherit;background:#fff}
input[type=tel]:focus-visible{outline:3px solid #1c1917;outline-offset:2px;border-color:#1c1917}
.choix{display:grid;gap:.5rem}
.choix.courts{grid-template-columns:repeat(3,1fr)}
.choix label{position:relative;display:block}
.choix input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer}
.choix span{display:flex;align-items:center;justify-content:center;min-height:3rem;padding:.5rem .75rem;border:2px solid #d6d3d1;border-radius:10px;background:#fff;font-weight:600;text-align:center}
.choix input:checked+span{border-color:${COULEUR};background:${COULEUR};color:#fff}
.choix input:focus-visible+span{outline:3px solid #1c1917;outline-offset:2px}
.bouton,button{display:flex;align-items:center;justify-content:center;width:100%;min-height:3.25rem;padding:.75rem 1rem;border:0;border-radius:10px;background:${COULEUR};color:#fff;font:inherit;font-weight:700;text-align:center;text-decoration:none;cursor:pointer}
button{margin-top:1.75rem;font-size:1.0625rem}
.bouton:focus-visible,button:focus-visible{outline:3px solid #1c1917;outline-offset:2px}
.creneaux{display:grid;grid-template-columns:repeat(2,1fr);gap:.5rem}
.creneaux .bouton{padding:.75rem .25rem;white-space:nowrap}
.pied{margin:1.25rem 0 0;font-size:.9375rem;text-align:center;color:#57534e}
`;

/** Page complète. `pied` : rappel du numéro sous la carte, pour les pages qui ne le citent pas déjà. */
function gabarit(titre, contenu, pied = false) {
  return `<!doctype html>
<html lang="fr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="robots" content="noindex, nofollow">
<title>${e(titre)} – ${ENTREPRISE}</title>
<style>${STYLE}</style>
</head>
<body>
<main>
<p class="marque">${ENTREPRISE}</p>
<div class="carte">
${contenu}
</div>
${pied && TELEPHONE ? `<p class="pied">Une question ? <a href="${APPEL}">${TELEPHONE}</a></p>` : ''}
</main>
</body>
</html>`;
}

const quand = (r) => `${e(r.jour)}, entre ${e(r.de)} et ${e(r.a)}`;

function listeCreneaux(jours) {
  if (!jours.length) {
    return `<p>Aucun créneau de rappel n'est disponible pour le moment. Répondez à notre e-mail ou ${appelezNous} : nous conviendrons d'un horaire ensemble.</p>`;
  }
  return jours
    .map(
      (jour) =>
        `<h2>${e(majuscule(jour.titre))}</h2><div class="creneaux">${jour.creneaux
          .map((c) => `<a class="bouton" href="${e(c.lien)}">${e(c.de)} – ${e(c.a)}</a>`)
          .join('')}</div>`,
    )
    .join('');
}

function pageCreneaux(d) {
  const avis = {
    pris: 'Ce créneau vient d’être réservé. Merci d’en choisir un autre.',
    indisponible: 'Ce créneau n’est plus disponible. Merci d’en choisir un autre.',
  }[d.avis];
  return gabarit(
    'Choisissez votre créneau',
    `<h1>Choisissez votre créneau de rappel</h1>
${avis ? `<p class="alerte" role="alert">${avis}</p>` : '<p>Nous vous rappelons à l’horaire de votre choix.</p>'}
${listeCreneaux(d.jours)}`,
    d.jours.length > 0,
  );
}

function pageQuestions(d) {
  const erreurs = d.erreurs ?? [];
  const alertes = [
    erreurs.includes('telephone') ? 'Merci d’indiquer le numéro auquel vous rappeler.' : '',
    erreurs.includes('questions') ? 'Merci de choisir une réponse à chaque question.' : '',
  ].filter(Boolean);

  const blocs = d.questions
    .map((q, rang) => {
      const courts = q.reponses.every((r) => r.length <= 12) && q.reponses.length <= 3;
      const options = q.reponses
        .map(
          (reponse, i) =>
            `<label><input type="radio" name="${e(q.id)}" value="${i}"${d.saisie.reponses[rang] === i ? ' checked' : ''}${
              d.obligatoires ? ' required' : ''
            }><span>${e(reponse)}</span></label>`,
        )
        .join('');
      return `<fieldset><legend>${e(q.titre)}</legend><div class="choix${courts ? ' courts' : ''}">${options}</div></fieldset>`;
    })
    .join('\n');

  return gabarit(
    'Votre rappel',
    `<h1>Votre rappel</h1>
<p class="resume"><strong>${e(majuscule(d.creneau.jour))}</strong>entre ${e(d.creneau.de)} et ${e(d.creneau.a)}</p>
<p class="autre"><a href="${e(d.lien_creneaux)}">Choisir un autre créneau</a></p>
${alertes.map((texte) => `<p class="alerte" role="alert">${texte}</p>`).join('')}
<form method="post" action="${e(d.lien_formulaire)}">
<input type="hidden" name="ref" value="${e(d.demande.ref)}">
<input type="hidden" name="c" value="${e(d.creneau.code)}">
<label class="champ" for="tel">Numéro auquel vous rappeler</label>
<input id="tel" name="tel" type="tel" inputmode="tel" autocomplete="tel" required maxlength="30" value="${e(d.saisie.telephone)}">
${blocs}
<button type="submit">Confirmer mon rappel</button>
</form>`,
    true,
  );
}

function pageConfirmation(d) {
  return gabarit(
    'Rappel confirmé',
    `<h1>C’est noté !</h1>
<p>Nous vous rappelons <strong>${quand(d.rappel)}</strong>, au <strong>${e(d.telephone)}</strong>.</p>
<p>Un empêchement ? Répondez à notre e-mail ou ${appelezNous}.</p>`,
  );
}

function pageMessage(d) {
  const messages = {
    deja_reserve: [
      'Votre rappel est déjà enregistré',
      `<p>Nous vous rappelons <strong>${d.rappel ? quand(d.rappel) : 'à l’horaire convenu'}</strong>.</p>
<p>Pour changer d’horaire, répondez à notre e-mail ou ${appelezNous}.</p>`,
    ],
    erreur: [
      'Un problème technique est survenu',
      `<p>Votre rappel n’a pas pu être enregistré. Merci de réessayer dans quelques minutes, ou ${appelezNous}.</p>`,
    ],
    lien_invalide: [
      'Ce lien n’est plus valable',
      `<p>Pour convenir d’un rappel, répondez à notre e-mail ou ${appelezNous}.</p>`,
    ],
  };
  const [titre, contenu] = messages[d.code] ?? messages.lien_invalide;
  return gabarit(titre, `<h1>${titre}</h1>\n${contenu}`);
}

// ---------------------------------------------------------------- Une sortie par élément reçu

return $input.all().map((item) => {
  const d = item.json ?? {};

  if (d.action === 'envoyer') {
    return { json: { ...d, email_objet: String(R.email_objet ?? '').trim() || 'Votre demande de rappel', email_html: email(d) } };
  }
  if (d.action === 'sans_email') return { json: d };
  if (d.action === 'reserver') {
    return { json: { ...d, page_confirmation: pageConfirmation(d), page_erreur: pageMessage({ code: 'erreur' }) } };
  }
  if (d.action === 'page') {
    const ecrans = { questions: pageQuestions, creneaux: pageCreneaux, message: pageMessage };
    return { json: { ...d, page_html: (ecrans[d.ecran] ?? pageMessage)(d) } };
  }
  if (d.action === 'erreur') return { json: { ...d, page_erreur: pageMessage({ code: 'erreur' }) } };

  // Élément sans décision : il vient de « Mail ou clic ? » (lien incomplet) ou de l'échec de
  // « Retrouver la demande ». Demande introuvable = lien périmé ; toute autre erreur = panne Gmail.
  const introuvable = d.error === undefined || /not found|not be found|invalid (?:\w+ )?id/i.test(String(d.error));
  if (!introuvable) return { json: { action: 'erreur', detail: String(d.error), page_erreur: pageMessage({ code: 'erreur' }) } };
  return { json: { action: 'page', ecran: 'message', code: 'lien_invalide', page_html: pageMessage({ code: 'lien_invalide' }) } };
});
